pub(super) fn analysis__oracle_classification__normalize_oracle_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut config: Value;
    let mut no_oracle_risks: Value;
    let mut oracle_classes: Value;
    let mut semantic_guards: Value;
    let mut test_sources: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    oracle_classes = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("oracle_classes"),
            Value::Array(vec![]),
        ))? {
            let mut oc = current;
            if !(oc.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__oracle_classification__normalize_oracle_class(
                oc.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    semantic_guards = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("semantic_guards"),
            Value::Array(vec![]),
        ))? {
            let mut sg = current;
            if !(sg.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__oracle_classification__normalize_semantic_guard(
                sg.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    no_oracle_risks = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("no_oracle_risks"),
            Value::Array(vec![]),
        ))? {
            let mut nor = current;
            if !(nor.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__oracle_classification__normalize_no_oracle_risk(
                nor.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    test_sources = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("test_sources"), Value::Array(vec![])))? {
            let mut ts = current;
            if !(ts.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__oracle_classification__normalize_test_source(
                ts.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("oracle_classes".into(), oracle_classes.clone()),
            ("semantic_guards".into(), semantic_guards.clone()),
            ("no_oracle_risks".into(), no_oracle_risks.clone()),
            ("test_sources".into(), test_sources.clone()),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "limits".into(),
                analysis__oracle_classification__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
            (
                "oracle_taxonomy_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("oracle_taxonomy_available"),
                    json!(false)
                ))),
            ),
            (
                "semantic_guard_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("semantic_guard_available"),
                    json!(false)
                ))),
            ),
            (
                "critical_risk_coverage_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("critical_risk_coverage_available"),
                    json!(false)
                ))),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

